type Product = { id: string; createdAt: string; name: string; priceCents: number };
type ProductPatch = Partial<Omit<Product, 'id' | 'createdAt'>>;

export function projectProductPatch(_input: Partial<Product>): ProductPatch {
  return {};
}

problems.solutionCode:
type Product = { id: string; createdAt: string; name: string; priceCents: number };
type ProductPatch = Partial<Omit<Product, 'id' | 'createdAt'>>;

export function projectProductPatch(input: Partial<Product>): ProductPatch {
  const result: ProductPatch = {};
  for (const key of ['name', 'priceCents'] as const) {
    if (!Object.hasOwn(input, key)) continue;
    if (key === 'name') {
      if (input.name !== undefined) result.name = input.name;
    } else if (input.priceCents !== undefined) {
      result.priceCents = input.priceCents;
    }
  }
  return result;
}

