problems.solutionCode:
type MemberProfile = { displayName: string; preferences: { email: boolean; sms: boolean } };
type MemberProfilePatch = Partial<Pick<MemberProfile, 'displayName' | 'preferences'>>;

export function applyMemberProfilePatch(profile: MemberProfile, patch: MemberProfilePatch): MemberProfile {
  if (patch.preferences !== undefined && (typeof patch.preferences.email !== 'boolean' || typeof patch.preferences.sms !== 'boolean')) {
    throw new TypeError('A preferences replacement must include both settings');
  }
  return { ...profile, ...patch };
}

problems.trapMutant:
type MemberProfile = { displayName: string; preferences: { email: boolean; sms: boolean } };
type MemberProfilePatch = Partial<Pick<MemberProfile, 'displayName' | 'preferences'>>;

export function applyMemberProfilePatch(profile: MemberProfile, patch: MemberProfilePatch): MemberProfile {
  return { ...profile, ...patch, preferences: { ...profile.preferences, ...patch.preferences } };
}

problems.starterCode:
type OrderStatus = 'pending' | 'paid' | 'shipped' | 'cancelled';
export const ORDER_STATUS_LABELS: Partial<Record<OrderStatus, string>> = { pending: 'Awaiting payment' };

export function getOrderStatusLabel(_status: OrderStatus): string | undefined {
  return undefined;
}

problems.solutionCode:
type OrderStatus = 'pending' | 'paid' | 'shipped' | 'cancelled';
export const ORDER_STATUS_LABELS: Record<OrderStatus, string> = {
  pending: 'Awaiting payment',
  paid: 'Payment confirmed',
  shipped: 'In transit',
  cancelled: 'Cancelled',
};

export function getOrderStatusLabel(status: OrderStatus): string | undefined {
  if (!Object.hasOwn(ORDER_STATUS_LABELS, status)) return undefined;
  return ORDER_STATUS_LABELS[status];
}

